  /**
   * Method under test:
   * {@link SmartContractOuterClass.ContractState#parseFrom(InputStream, ExtensionRegistryLite)}
   */
  @Test
  public void testContractStateParseFrom10() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt())).thenThrow(new IOException("foo"));

    // Act and Assert
    assertThrows(IOException.class,
        () -> SmartContractOuterClass.ContractState.parseFrom(input, ExtensionRegistryLite.getEmptyRegistry()));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

